from pathlib import Path
import json
HERE=Path(__file__).resolve().parent;out=HERE/'outputs/validation_r2_analysis';data=json.loads((out/'aggregate.json').read_text(encoding='utf-8'))
def get(cond,method):return next(r for r in data if r['condition']==cond and r['method']==method)
a=get('tracking','shared');b=get('tracking','shared_free_waist');c=get('tracking','shared_no_frame');reduction=100*(1-a['waist_peak_to_peak_deg']/b['waist_peak_to_peak_deg'])
lines=['# 修正版独立验证：结论与限制','','最终协议包含 120 次试验，种子 400–407。第一轮种子 300–307 的 120 次结果已用于修改支撑转移，因此不合并进本表。全部模型、控制快照、失败轨迹和输入包均保留。','','## 可以据此陈述的结果','',f"1. **腰部晃动受到抑制。** 在输入处理、场景和其他控制完全相同的配对消融中，允许腰部持续参与时，搬运阶段腰部最大角度变化范围均值为 {b['waist_peak_to_peak_deg']:.2f}°；阶段姿态保持后为 {a['waist_peak_to_peak_deg']:.2f}°，降低 {reduction:.1f}%。腰部角速度 RMS 从 {b['waist_rms_velocity_deg_s']:.2f}°/s 降至 {a['waist_rms_velocity_deg_s']:.2f}°/s。两者都是 8/8 成功，不能说腰部模块在这个条件下提高了成功率。",f"2. **稳定性存在跟踪代价。** 同一对照中，手部位置 RMSE 从 {b['hand_rmse_mm']:.2f} mm 上升到 {a['hand_rmse_mm']:.2f} mm。减少身体冗余运动占用了一部分姿态补偿能力；结论是更稳定的动作与可接受任务误差之间的取舍，不是所有指标都更优。",'3. **输入处理对受扰任务关键。** 6 mm / 80 ms / 10% 条件下，直接跟踪和只保持腰部姿态都是 0/8，完整方法 8/8；12 mm / 160 ms / 20% 条件下，直接跟踪 0/8，完整方法 8/8。强扰动下基线均在抓取或抬升前后失败，没有进入搬运阶段，所以不计算其搬运腰部指标。',f"4. **底盘重投影改善手部误差与耗时。** 去掉重投影仍为 8/8，但 RMSE 为 {c['hand_rmse_mm']:.2f} mm，完整方法为 {a['hand_rmse_mm']:.2f} mm；平均成功耗时分别为 {c['mean_success_time_s']:.2f} s 与 {a['mean_success_time_s']:.2f} s。这支持精度与效率收益，不能写成成功率收益。",'5. **支撑反馈有可追查的修复证据，但统计优势有限。** 第一轮的首次接触固定目标在低台面会让托盘悬停，修正版改为低速下放直到桌面承重。在最终受扰条件下，去掉该模块为 7/8，完整方法 8/8；仅一对结果改变，不足以证明总体成功率有显著提升。','6. **避障功能有效于设定走廊。** 去掉让行预测的 8 次均因障碍接触终止。开启时完整方法在对应受扰场景中无碰撞完成 8/8，平均等待约 4.8 s。障碍状态直接从仿真读取，未验证视觉感知或未知环境。','','## 主要结果','','|输入条件|方法|成功|腰部范围均值/°|手部 RMSE/mm|成功耗时/s|','|---|---|---:|---:|---:|---:|']
names={'adaptive':'直接跟踪','stable':'仅腰部稳定','shared_free_waist':'去掉腰部稳定','shared_no_contact':'去掉支撑反馈','shared_no_frame':'去掉坐标补偿','shared':'完整方法'}
for cond in ['clean','tracking','severe','without_safety']:
    for r in [x for x in data if x['condition']==cond]:
        def num(k):return '—'if r[k]is None else f'{r[k]:.2f}'
        lines.append(f"|{cond}|{names[r['method']]}|{r['success']}/{r['n']}|{num('waist_peak_to_peak_deg')}|{num('hand_rmse_mm')}|{num('mean_success_time_s')}|")
lines+=['','## 统计口径','','每组只有 8 个独立场景种子，8/8 对应 Wilson 95% 区间约 67.6%–100%。结果支持这组受控条件下的改进，不能把“测试全成功”写成确定的 100% 可靠性。成功率、失败类型计入所有试验。角度/误差统计对全部已进入搬运的轨迹计算，包括后来失败的轨迹；时间只对成功试验求均值。不同方法的失败时刻不同，完整时长可比性有限。','','腰部指标为三个关节搬运阶段各自峰峰值中的最大值，再按 8 个试验取均值；不是机身整体倾角。手部 RMSE 对无噪声目标求取，双手等权，搬运期间 10 Hz 采样。所有数据在 `per_trial.json`。','', '## 第一轮失败如何处理','','`../validation/` 保留首次 120 次测试；`../validation_analysis/` 是其完整统计。研发根据这些失败修改了放置逻辑，所以修正版只使用新的种子 400–407。并未删除失败样例、修改旧记录或把已用于调参的数据重新称作独立验证。冻结协议与源码快照位于两轮各自目录，当前源代码的后续变化不改变快照。','','## 模型与成果边界','','- 基于项目 YMBOT 模型，真实推进轮地接触、自由负载、重力和限矩关节动力学；并非运行中绑定货物或重置物体位置。','- 腰部姿态保持是 IK 自由度分配及物理伺服，不是锁死仿真关节。抓取和改变高度时仍允许腰部运动。','- 机器人、物体和障碍位姿是理想仿真观测；没有加入视觉识别误差，也没有连接真实 VR 头显。','- 输入为合成数据。没有真人参与，没有验证操作员工作负荷、固定劳动时间内效率、数据采集体验或模仿学习效果。','- 研究夹爪、脚轮近似、环境碰撞代理与执行器参数需要真机辨识；全身网格自碰撞尚未验证。','- V2 的重载低摩擦 128 次实验是另外一组数据，不能和本轮结果拼成一个统一成功率。','- 本轮展示的是控制系统构建、明确问题、改进、失败修复与消融证据，未声称新的控制理论、完整论文学习系统复现或保证国家级立项等级。','','## 最直接的验收方式','','打开项目根目录的“打开仿真验收.cmd”。先看动态任务完整视频，再看同条件腰部对照；双击“重新运行复杂任务.cmd”复算。`../validation_r2_verification.json` 记录独立状态复核；`../delivery_verification.json` 记录视频解码和页面资源校验。']
(out/'结论与限制.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
note=f'''# 仿真成果验收说明（V3，2026-11-15）

先双击“打开仿真验收.cmd”，刷新原有页面后应看到“动态环境下的双臂共享控制”。

本次针对“任务太简单、缺少研究深度”和“身体一直晃”作了实质修改：车轮接触驱动、阶段腰部稳定、合成遥操作输入扰动、动态障碍让行、低/高台面支撑放置，并有独立验证和消融。

- 同条件腰部变化范围均值：{b['waist_peak_to_peak_deg']:.2f}° → {a['waist_peak_to_peak_deg']:.2f}°；手部 RMSE 有 5.92 → 9.65 mm 的代价。
- 6 mm 噪声、80 ms 延迟、10% 丢包：直接跟踪 0/8，完整方法 8/8。
- 12 mm、160 ms、20%：直接跟踪 0/8，完整方法 8/8。
- 关闭动态让行：8/8 因碰撞终止。
- 最终 120 次独立验证，另保留第一轮 120 次及 V2 128 次结果。每组 8 个种子，不能外推真机可靠性。

页面中提供完整任务、低台面任务、腰部对照、重载对照和数据链接。三维回放可旋转视角；实时入口可用键盘；重新运行入口真正从初始场景推进动力学。

详细运行说明：`simulation/research/README.md`。
研究问题、方法和引用：`simulation/research/研究设计与来源.md`。
结果解释与限制：`simulation/research/outputs/validation_r2_analysis/结论与限制.md`。

本轮没有制作 PPT、没有连接真实 VR 或真机、没有训练学习策略。国家级认定仍取决于学院评审与名额；当前交付是可运行、可演示、可复查的仿真研究进展。
'''
(HERE.parent.parent/'仿真成果验收说明.md').write_text(note,encoding='utf-8');print(out/'结论与限制.md')
